package user

import (
	"fmt"

	"github.com/google/uuid"
)

// ID uniquely identifies a User. It is generated by the domain (UUIDv7,
// time-ordered), not by the database, so a User is complete from creation.
type ID uuid.UUID

// NewID returns a new time-ordered ID.
func NewID() ID {
	return ID(uuid.Must(uuid.NewV7()))
}

// ParseID parses the canonical string form, e.g. from a URL path.
func ParseID(s string) (ID, error) {
	u, err := uuid.Parse(s)
	if err != nil {
		return ID{}, fmt.Errorf("%w: %q", ErrInvalidID, s)
	}
	return ID(u), nil
}

func (id ID) String() string {
	return uuid.UUID(id).String()
}
